public class BoxBlurFilterTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static String pixel(java.awt.image.BufferedImage img, int x, int y) {
        if (img == null) {
            return "null-image";
        }
        if (x < 0 || y < 0 || x >= img.getWidth() || y >= img.getHeight()) {
            return "out-of-range";
        }
        return String.format("#%06X", img.getRGB(x, y) & 0xFFFFFF);
    }

    static int widthOf(java.awt.image.BufferedImage img) {
        return img == null ? -1 : img.getWidth();
    }

    static int heightOf(java.awt.image.BufferedImage img) {
        return img == null ? -1 : img.getHeight();
    }

    static java.awt.image.BufferedImage spot() {
        java.awt.image.BufferedImage img = new java.awt.image.BufferedImage(
                4, 4, java.awt.image.BufferedImage.TYPE_INT_RGB);
        for (int y = 0; y < 4; y++) {
            for (int x = 0; x < 4; x++) {
                img.setRGB(x, y, 0x101010);
            }
        }
        img.setRGB(1, 1, 0xF0C060);
        img.setRGB(2, 2, 0x204080);
        return img;
    }

    static java.awt.image.BufferedImage flat(int w, int h, int rgb) {
        java.awt.image.BufferedImage img = new java.awt.image.BufferedImage(
                w, h, java.awt.image.BufferedImage.TYPE_INT_RGB);
        for (int y = 0; y < h; y++) {
            for (int x = 0; x < w; x++) {
                img.setRGB(x, y, rgb);
            }
        }
        return img;
    }

    public static void main(String[] args) {
        try {
            java.awt.image.BufferedImage src = spot();
            java.awt.image.BufferedImage blurred = BoxBlurFilter.blur(src);
            java.awt.image.BufferedImage plain = BoxBlurFilter.blur(flat(3, 3, 0x336699));
            check("blurred width", 4, widthOf(blurred));
            check("blurred height", 4, heightOf(blurred));
            check("centre of the bright spot (1,1)", "#2A2825", pixel(blurred, 1, 1));
            check("clamped bottom-right corner (3,3)", "#11151C", pixel(blurred, 3, 3));
            check("corner uses clamped samples (0,0)", "#282318", pixel(blurred, 0, 0));
            check("far corner is untouched dark (3,0)", "#101010", pixel(blurred, 3, 0));
            check("source is untouched at (1,1)", "#F0C060", pixel(src, 1, 1));
            check("a flat image blurs to itself", "#336699", pixel(plain, 1, 1));
            check("flat image corner too", "#336699", pixel(plain, 0, 0));
        } catch (Exception e) {
            failures++;
            System.out.println("FAIL  unexpected exception: " + e);
        }
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

