import java.awt.image.BufferedImage;

public class BoxBlurFilter {

    public static BufferedImage blur(BufferedImage src) {
        int w = src.getWidth();
        int h = src.getHeight();
        BufferedImage out = new BufferedImage(w, h, BufferedImage.TYPE_INT_RGB);

        for (int y = 0; y < h; y++) {
            for (int x = 0; x < w; x++) {
                int sumR = 0;
                int sumG = 0;
                int sumB = 0;
                for (int dy = -1; dy <= 1; dy++) {
                    for (int dx = -1; dx <= 1; dx++) {
                        int sx = Math.min(Math.max(x + dx, 0), w - 1);
                        int sy = Math.min(Math.max(y + dy, 0), h - 1);
                        int rgb = src.getRGB(sx, sy);
                        sumR += (rgb >> 16) & 0xFF;
                        sumG += (rgb >> 8) & 0xFF;
                        sumB += rgb & 0xFF;
                    }
                }
                int r = sumR / 9;
                int g = sumG / 9;
                int b = sumB / 9;
                out.setRGB(x, y, (r << 16) | (g << 8) | b);
            }
        }
        return out;
    }
}
